const STATE = require('STATE')
const statedb = STATE(__filename)
const { sdb, get } = statedb(fallback_module)
const net = require('net_helper')

module.exports = node_selector

async function node_selector(opts = {}) {
  const { id, sdb } = await get(opts.sid)
  const { drive } = sdb
  const on = { style: inject, data: ondata }

  const el = document.createElement('div')
  const shadow = el.attachShadow({ mode: 'closed' })
  shadow.innerHTML = `
    <div class="selector"></div>
    <style></style>
  `

  const style = shadow.querySelector('style')
  const container = shadow.querySelector('.selector')
  const { io, _: send } = net(id)

  io.on.home_contents = function (m) {
    if (m.type === 'update') render(m.data)
  }
  el.invite = io.invite('home_contents', { node_selector: id })
  el.close = close

  await sdb.watch(onbatch)
  return el

  async function onbatch(batch) {
    for (const { type, paths } of batch) {
      const data = await Promise.all(paths.map(path => drive.get(path).then(file => file.raw)))
      const handler = on[type] || fail
      await handler(data, type)
    }
  }

  function inject(data) {
    style.textContent = data[0]
  }

  function ondata(data) {
    render(data[0])
  }

  function render(data = {}) {
    const selected = data.selected || 'node4'
    const source = Array.isArray(data.accounts) ? data.accounts : defaultAccounts()
    const accounts = source.filter(account => (account.id === 'node4' || account.id === 'node6') && account.status === 'online')
    if (!accounts.length) {
      container.classList.remove('open')
      container.replaceChildren()
      return
    }
    const current = accounts.find(account => account.id === selected)
    const open = container.classList.contains('open')

    container.innerHTML = `
      <button class="selector-button" type="button" aria-label="Select Lightning node" aria-expanded="${open}">
        <span class="avatar" style="background:${current?.color || '#777'}">${current ? initial(current) : '+'}</span>
      </button>
      <div class="drawer" aria-hidden="${!open}">
        <div class="drawer-title">
          <span>Select Lightning node</span>
          <button class="close" type="button" aria-label="Close node selector">&#215;</button>
        </div>
        ${accounts.map(account => `
          <button class="account ${account.id === selected ? 'active' : ''}" type="button" data-node="${account.id}">
            <span class="avatar" style="background:${account.color || '#111'}">${initial(account)}</span>
            <span class="account-copy">
              <strong>${name(account)}</strong>
              <small>${account.status || 'offline'} · ${Number(account.balance?.sats || 0).toLocaleString()} sats</small>
            </span>
            <span class="check">${account.id === selected ? '&#10003;' : ''}</span>
          </button>
        `).join('')}
      </div>
    `

    const trigger = container.querySelector('.selector-button')
    const drawer = container.querySelector('.drawer')
    trigger.onclick = function () {
      const open = container.classList.toggle('open')
      trigger.setAttribute('aria-expanded', String(open))
      drawer.setAttribute('aria-hidden', String(!open))
    }
    container.querySelector('.close').onclick = close

    container.querySelectorAll('.account').forEach(button => {
      button.onclick = function () {
        const nodeId = button.dataset.node
        container.classList.remove('open')
        if (nodeId !== selected) send.home_contents('select', { cause: [] }, { nodeId })
      }
    })
  }

  function close() {
    container.classList.remove('open')
    container.querySelector('.selector-button')?.setAttribute('aria-expanded', 'false')
    container.querySelector('.drawer')?.setAttribute('aria-hidden', 'true')
  }

  function defaultAccounts() {
    return [
      { id: 'node4', alias: 'Node 4', status: 'offline', balance: { sats: 0 } },
      { id: 'node6', alias: 'Node 6', status: 'offline', balance: { sats: 0 } }
    ]
  }

  function name(account) {
    if (account?.alias && account.alias !== 'Unknown') return account.alias
    return account?.id ? account.id.replace('node', 'Node ') : 'Lightning node'
  }

  function initial(account) {
    return name(account).charAt(0).toUpperCase()
  }

  function fail(data, type) {
    throw new Error('invalid message', { cause: { data, type } })
  }
}

function fallback_module() {
  return {
    api,
    _: { net_helper: { $: '' } }
  }

  function api(opts) {
    if (!opts) opts = {}
    return {
      drive: {
        'style/': { 'node_selector.css': { '$ref': 'node_selector.css' } },
        'data/': { 'opts.json': { raw: opts || {} } }
      }
    }
  }
}
